                                                                        and company_id = (select id from flow.company where company_name = 'Solenrgi')) AS process_step_status_id,
                2350555 as created_by_id,
                now(),
                permit_revision_c_complete_date
         FROM flow.project
                  INNER JOIN blueraven.deal d
                             ON project.id = d.id
         where permit_revision_c_complete_date is not null
           and originator_id = 2)
        returning *),
     p as (
         select cfga.id as custom_field_group_assignment_id,cf.field_name,dt.data_type,dt.id as data_type_id
         from flow.custom_field_group_assignment cfga
                  inner join flow.custom_field_group cfg on cfg.id = cfga.custom_field_group_id
                  inner join flow.custom_field cf on cf.id = cfga.custom_field_id
                  inner join flow.company_data_type cdt on cdt.id = cf.company_data_type_id
                  inner join flow.data_type dt on dt.id = cdt.data_type_id
         where cfg.process_step_id = 1855
           and cf.archived is false and cfg.archived is false and cfga.archived is false
     )
insert into flow.project_process_step_custom_field_value(project_process_step_id, custom_field_group_assignment_id, date_value,
                                                         text_value,int_value,date_created, date_modified, created_by_id, modified_by_id)
    (select p1.id,p.custom_field_group_assignment_id,
            case when p.custom_field_group_assignment_id = 9485 then (( permit_pack_revision_requested_date AT TIME ZONE 'US/Mountain') AT TIME ZONE 'UTC')
                 when p.custom_field_group_assignment_id = 11825 then (( plan_set_created_date AT TIME ZONE 'US/Mountain') AT TIME ZONE 'UTC')
                 else null end,
            case when p.custom_field_group_assignment_id = 9485 then permit_revision_a_reason else null end,
            case when p.custom_field_group_assignment_id = 11851 then (select id from flow.list_of_value where parent_id = 2198
                                                                                                         and name = d2.engineering_stamp_required)
                 when p.custom_field_group_assignment_id = 11864 then (select id from flow.list_of_value where parent_id = 2211
                                                                                                         and name = d2.electrical_engineering_stamp_required)
                 when p.custom_field_group_assignment_id = 12280 then (select id from flow.list_of_value where parent_id = 2107
                                                                                                          and name = d2.engineering_stamp_type)
                 when p.custom_field_group_assignment_id = 11461 then (select id from flow.list_of_value where parent_id = 2029
                                                                                                          and name = d2.racking_type)
                 when p.custom_field_group_assignment_id = 11838 then (select id from flow.list_of_value where parent_id = 2367
                                                                                                         and name = CASE WHEN
                                                                                                                                 non_standard_installation_work like any (array['%Placard Required%'])
                                                                                                                             THEN 'YES'
                                                                                                                         WHEN non_standard_installation_work is null and plan_set_created_date is not null
                                                                                                                             THEN null
                                                                                                                         ELSE 'NO' end)
                 when p.custom_field_group_assignment_id = 7509 then (select up.id from blueraven.deal d
                                                                                           inner join blueraven.user u on u.first_name|| ' '||u.last_name = d.plan_set_created_by
                                                                                           inner join flow.user_position up on up.user_id = u.id
                                                                     where d.id = d2.id and up.position_id in (24,25,26,120) and d.plan_set_created_by is not null limit 1)
                 else null end,
            now(),now(),2350555,2350555
     from blueraven.deal d2

              inner join process_step1 p1 on p1.project_id = d2.id
              cross join p
    );

