/*Schedule AHJ Re-inspection with Customer*/
with active_step as (
    INSERT INTO flow.project_process_step (project_id, process_step_id, company_process_step_status_type_id, created_by_id,date_created)
        (SELECT project.id,
                2323,
                (SELECT id FROM flow.company_process_step_status_type WHERE process_step_status_type = 'Active'
                                                                        and company_id = (select id from flow.company where company_name = 'Solenrgi')) AS process_step_status_id,
                2350555 as created_by_id,
                (now() + interval '1 day')
         FROM flow.project
                  INNER JOIN blueraven.deal d
                             ON project.id = d.id
         where originator_id = 2 and (
                                      (ahj_inspection_work_required IS NULL OR ahj_inspection_work_verified_date IS NOT NULL) AND
                                      (
                                              (ahj_inspection_outcome = 'Fail' AND (AHJ_reinspection_scheduled is null OR ahj_reinspection_date IS NULL)) OR
                                              (ahj_reinspection_outcome = 'Fail' AND (ahj_reinspection_b_scheduled is null OR
                                                                                      ahj_reinspection_b_date is null or ahj_reinspection_b_outcome = 'Fail')) OR
                                              (additional_ahj_inspection_date :: DATE <= (now() at time zone 'US/Mountain') :: DATE
                                                  AND additional_ahj_inspection_outcome = 'Fail')
                                          )
             )) returning *),
     p as (
         select cfga.id as custom_field_group_assignment_id,cf.field_name,dt.data_type,dt.id as data_type_id
         from flow.custom_field_group_assignment cfga
                  inner join flow.custom_field_group cfg on cfg.id = cfga.custom_field_group_id
                  inner join flow.custom_field cf on cf.id = cfga.custom_field_id
                  inner join flow.company_data_type cdt on cdt.id = cf.company_data_type_id
                  inner join flow.data_type dt on dt.id = cdt.data_type_id
         where cfg.process_step_id = 2323
           and cf.archived is false and cfg.archived is false and cfga.archived is false
     )
insert into flow.project_process_step_custom_field_value(project_process_step_id, custom_field_group_assignment_id,date_value,
                                                         int_value,date_created, date_modified, created_by_id, modified_by_id)
    (select p1.id,p.custom_field_group_assignment_id,
            case when p.custom_field_group_assignment_id = 8718 then ((ahj_inspection_scheduled_date  AT TIME ZONE 'US/Mountain') AT TIME ZONE 'UTC') else null end,

              case  when p.custom_field_group_assignment_id = 8731 then (select id from flow.list_of_value where parent_id = 1327
                                                                                                         and name::boolean = d2.technician_site_required)
                else null end,
            now(),now(),2350555,2350555
     from blueraven.deal d2

              inner join active_step p1 on p1.project_id = d2.id
              cross join p
    );


with process_step1 as (
    INSERT INTO flow.project_process_step (project_id, process_step_id, company_process_step_status_type_id, created_by_id,date_created,process_step_complete_date)
        (with deals as (
            SELECT d.id,ahj_reinspection_scheduled as complete_date
            FROM flow.project
                     INNER JOIN blueraven.deal d
                                ON project.id = d.id
            where
                ahj_reinspection_date is not null
              and originator_id = 2
            union all
            select deal_id,dce.updated as complete_date
            from blueraven.deal_calendar_event dce
                     inner join blueraven.deal d on d.id = dce.deal_id
            where  originator_id = 2 and work_type_id = 5 and deleted is false
              and d.ahj_reinspection_date::date != dce.start_time::date
            union all
            SELECT dce.deal_id,dce.updated as complete_date
            FROM  blueraven.deal_calendar_event dce
                      inner join blueraven.deal d69 on d69.id = dce.deal_id and d69.originator_id = 2
            where  work_type_id = 5 and deleted is false
              and not exists (
                    SELECT d.id
                    FROM flow.project
                             INNER JOIN blueraven.deal d
                                        ON project.id = d.id
                    where
                        ahj_reinspection_date is not null
                      and originator_id = 2))
         SELECT project.id,
                2323,
                (SELECT id FROM flow.company_process_step_status_type WHERE process_step_status_type = 'Complete'
                                                                        and company_id = (select id from flow.company where company_name = 'Solenrgi')) AS process_step_status_id,
                2350555 as created_by_id,
                now(),
                d1.complete_date
         FROM flow.project
                  INNER JOIN blueraven.deal d
                             ON project.id = d.id
                  inner join deals d1 on d1.id = d.id)returning *),
     p as (
         select cfga.id as custom_field_group_assignment_id,cf.field_name,dt.data_type,dt.id as data_type_id
         from flow.custom_field_group_assignment cfga
                  inner join flow.custom_field_group cfg on cfg.id = cfga.custom_field_group_id
                  inner join flow.custom_field cf on cf.id = cfga.custom_field_id
                  inner join flow.company_data_type cdt on cdt.id = cf.company_data_type_id
                  inner join flow.data_type dt on dt.id = cdt.data_type_id
         where cfg.process_step_id = 2323
           and cf.archived is false and cfg.archived is false and cfga.archived is false
     )
