    (select p1.id,p.custom_field_group_assignment_id,
            case when p.custom_field_group_assignment_id = 8718 then ((ahj_reinspection_scheduled  AT TIME ZONE 'US/Mountain') AT TIME ZONE 'UTC')::date else null end,
